try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT p.title,p.slug,pe.currency,pe.capacity,pe.attendance_type,t.* FROM pages p JOIN page_events pe ON pe.page_id=p.id JOIN event_ticket_types t ON t.page_id=p.id WHERE p.id=? AND p.page_type="event" AND t.id=? AND t.is_active=1 AND t.deleted_at IS NULL FOR UPDATE');$q->execute([$pageId,$ticketId]);$t=$q->fetch();if(!$t)throw new RuntimeException('Ticket unavailable.');if(($t['attendance_type']??'open')!=='ticketed')throw new RuntimeException('This is an open event and does not require tickets.');if((int)$t['price_minor']<1)throw new RuntimeException('This ticket does not have a valid price.');if($qty>(int)$t['max_per_order'])throw new RuntimeException('This order exceeds the ticket limit.');$left=max(0,(int)$t['quantity_total']-(int)$t['quantity_sold']);if($qty>$left)throw new RuntimeException('Not enough tickets remaining.');$q=$pdo->prepare('SELECT COALESCE(SUM(quantity),0) FROM event_orders WHERE page_id=? AND payment_status IN ("free","paid","pending") FOR UPDATE');$q->execute([$pageId]);$reserved=(int)$q->fetchColumn();if($reserved+$qty>(int)$t['capacity'])throw new RuntimeException('The event has reached its capacity.');$total=(int)$t['price_minor']*$qty;$ref='XEV-'.strtoupper(bin2hex(random_bytes(10)));$code='XEVT-'.strtoupper(bin2hex(random_bytes(7)));$status='pending';$q=$pdo->prepare('INSERT INTO event_orders(page_id,ticket_type_id,order_ref,ticket_code,attendee_name,attendee_email,attendee_phone,quantity,unit_price_minor,total_minor,currency,payment_status,created_at,updated_at)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$q->execute([$pageId,$ticketId,$ref,$code,mb_substr($name,0,120),mb_substr($email,0,120),mb_substr($phone,0,40),$qty,(int)$t['price_minor'],$total,$t['currency']?:'NGN',$status]);$pdo->prepare('UPDATE event_ticket_types SET quantity_sold=quantity_sold+? WHERE id=?')->execute([$qty,$ticketId]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();fail_checkout($e instanceof RuntimeException?$e->getMessage():'Registration failed.');}
if($total===0){header('Location: event_ticket.php?ref='.rawurlencode($ref));exit;}
