$base=rtrim(getenv('PANDASCROW_API_BASE')?:'https://sandbox.pandascrow.io','/');$callback=xinng_public_base_url().'/event_ticket.php?ref='.rawurlencode($ref);$payload=['uuid'=>$owner,'type'=>'onetime','currency'=>$t['currency']?:'NGN','amount'=>number_format($total/100,2,'.',''),'name'=>$t['title'].' — '.$t['name'],'description'=>'Ticket order '.$ref,'is_phone_required'=>true,'redirect_link'=>$callback];$ch=curl_init($base.'/payme');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>25,CURLOPT_HTTPHEADER=>['Token: '.$token,'Content-Type: application/json','Accept: application/json'],CURLOPT_POSTFIELDS=>json_encode($payload)]);$raw=curl_exec($ch);$http=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$data=json_decode((string)$raw,true);$url=$data['payment_url']??$data['checkout_url']??$data['url']??$data['link']??null;if($http<200||$http>=300||!filter_var($url,FILTER_VALIDATE_URL))fail_checkout('Pandascrow could not start payment. No charge was made.',502);$pdo->prepare('UPDATE event_orders SET pandascrow_payment_url=?,updated_at=NOW() WHERE order_ref=?')->execute([$url,$ref]);header('Location: '.$url,true,303);
